const upsertAddressCounters = `-- name: UpsertAddressCounters :exec
INSERT INTO address_counters (address, ban_count, ban_quiet_since, challenge_count, challenge_quiet_since, last_ban_at,
    last_ban_ends_at, last_challenge_at, last_source, country, asn, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (address) DO UPDATE SET ban_count = excluded.ban_count, ban_quiet_since = excluded.ban_quiet_since,
    challenge_count = excluded.challenge_count, challenge_quiet_since = excluded.challenge_quiet_since,
    last_ban_at = excluded.last_ban_at, last_ban_ends_at = excluded.last_ban_ends_at,
    last_challenge_at = excluded.last_challenge_at, last_source = excluded.last_source, country = excluded.country,
    asn = excluded.asn, updated_at = excluded.updated_at
`

type UpsertAddressCountersParams struct {
	Address             string
	BanCount            int64
	BanQuietSince       int64
	ChallengeCount      int64
	ChallengeQuietSince int64
	LastBanAt           sql.NullInt64
	LastBanEndsAt       sql.NullInt64
	LastChallengeAt     sql.NullInt64
	LastSource          string
	Country             string
	Asn                 int64
	CreatedAt           int64
	UpdatedAt           int64
}

func (q *Queries) UpsertAddressCounters(ctx context.Context, arg UpsertAddressCountersParams) error {
	_, err := q.db.ExecContext(ctx, upsertAddressCounters,
		arg.Address,
		arg.BanCount,
		arg.BanQuietSince,
		arg.ChallengeCount,
		arg.ChallengeQuietSince,
		arg.LastBanAt,
		arg.LastBanEndsAt,
		arg.LastChallengeAt,
		arg.LastSource,
		arg.Country,
		arg.Asn,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}
